import sys as _mbsys; _mbsys.path.insert(0, 'C:\\Users\\Nanja\\MachineBench\\machinebench\\bridge'); import mb_cam as mb
def run(_context):
    import json, adsk.core, adsk.fusion, adsk.cam

    # Let's examine all faces and categorize by normal direction
    faces = mb.faces(body_index=0)

    print('=== FACE NORMAL CATEGORIES ===')
    z_normal_faces = []
    y_normal_faces = []
    x_normal_faces = []
    other_faces = []

    for f in faces:
        nx, ny, nz = f['normal']
        # Classify by dominant normal direction
        if abs(nz) > 0.5:
            z_normal_faces.append(f)
        elif abs(ny) > 0.5:
            y_normal_faces.append(f)
        elif abs(nx) > 0.5:
            x_normal_faces.append(f)
        else:
            other_faces.append(f)

    print(f'\nZ-normal faces (horizontal, accessible from +Z): {len(z_normal_faces)}')
    for f in z_normal_faces:
        print(f'  idx={f["index"]:3d}  type={f["type"]:10s}  area={f["area_mm2"]:10.2f}  normal=[{f["normal"][0]:.2f},{f["normal"][1]:.2f},{f["normal"][2]:.2f}]  centroid=[{f["centroid_mm"][0]:.2f},{f["centroid_mm"][1]:.2f},{f["centroid_mm"][2]:.2f}]')

    print(f'\nY-normal faces: {len(y_normal_faces)}')
    for f in y_normal_faces:
        print(f'  idx={f["index"]:3d}  type={f["type"]:10s}  area={f["area_mm2"]:10.2f}  normal=[{f["normal"][0]:.2f},{f["normal"][1]:.2f},{f["normal"][2]:.2f}]  centroid=[{f["centroid_mm"][0]:.2f},{f["centroid_mm"][1]:.2f},{f["centroid_mm"][2]:.2f}]')

    print(f'\nX-normal faces: {len(x_normal_faces)}')
    for f in x_normal_faces:
        print(f'  idx={f["index"]:3d}  type={f["type"]:10s}  area={f["area_mm2"]:10.2f}  normal=[{f["normal"][0]:.2f},{f["normal"][1]:.2f},{f["normal"][2]:.2f}]  centroid=[{f["centroid_mm"][0]:.2f},{f["centroid_mm"][1]:.2f},{f["centroid_mm"][2]:.2f}]')

    print(f'\nOther faces: {len(other_faces)}')
    for f in other_faces:
        print(f'  idx={f["index"]:3d}  type={f["type"]:10s}  area={f["area_mm2"]:10.2f}  normal=[{f["normal"][0]:.2f},{f["normal"][1]:.2f},{f["normal"][2]:.2f}]  centroid=[{f["centroid_mm"][0]:.2f},{f["centroid_mm"][1]:.2f},{f["centroid_mm"][2]:.2f}]')

